using System.Data;
using Dapper;
using Microsoft.Data.SqlClient;
using PosApi.Auth;
using PosApi.Common;
using PosApi.Data;

namespace PosApi.Features.Sales;

public sealed record SaleLineInput(
    string ItemId,
    decimal Quantity,
    long UnitPriceH,
    long LineDiscountH,
    string? Note);

public sealed record SalePaymentInput(string Method, long AmountH, string? Reference);

public sealed record CommitSaleRequest(
    /*
     * One key per attempt, generated by the client.
     *
     * A retry after a timeout sends the same key, and the server returns the
     * original sale instead of creating a second one. Without it, a dropped
     * response means the client cannot tell success from failure — and retrying
     * is the reasonable thing to do.
     */
    string? IdempotencyKey,
    string BranchId,
    string? CustomerId,
    string? ServedByUserId,
    string? DiscountId,
    long DiscountH,
    long? TenderedH,
    IReadOnlyList<SaleLineInput> Lines,
    IReadOnlyList<SalePaymentInput> Payments,
    /*
     * Who approved a discount above its approval threshold. The signed-in
     * user may name themself (they must hold discounts.approve); naming
     * anyone else needs that person's password in ApproverPassword. Ignored
     * when the discount needs no approval.
     */
    string? ApprovedByUserId = null,
    string? ApproverPassword = null,
    /* dine_in | takeaway | delivery | other — shown on the kitchen board. */
    string? OrderType = null);

public sealed record VoidSaleRequest(string Reason);

public static class SalesEndpoints
{
    public static void MapSalesEndpoints(this IEndpointRouteBuilder app)
    {
        var group = app.MapGroup("/api/sales")
            .WithTags("Sales")
            .RequireAuthorization()
            .RequireRateLimiting("standard");

        group.MapPost("", CommitAsync)
             .RequireAuthorization(PermissionPolicy.For("pos.create_sale"));

        group.MapGet("/analytics", AnalyticsAsync)
             .RequireAuthorization(PermissionPolicy.For("dashboard.view"));

        group.MapGet("", ListAsync)
             .RequireAuthorization(PermissionPolicy.For("sales.view"));

        group.MapGet("/{saleId}", GetAsync)
             .RequireAuthorization(PermissionPolicy.For("sales.view_details"));

        group.MapPost("/{saleId}/void", VoidAsync)
             .RequireAuthorization(PermissionPolicy.For("sales.void"));
    }

    /// <summary>
    /// Commit a sale.
    ///
    /// The whole thing is one stored procedure call because the six writes it
    /// performs must succeed or fail together. Doing it here in six round trips
    /// would let a dropped connection halfway through leave stock reduced for a
    /// sale that does not exist.
    /// </summary>
    private static async Task<IResult> CommitAsync(
        CommitSaleRequest request,
        ISqlConnectionFactory db,
        ICurrentUser current,
        IPasswordHasher hasher,
        ILogger<Program> logger,
        CancellationToken ct)
    {
        if (request.Lines.Count == 0)
        {
            return Results.BadRequest(ApiError.Create(
                "empty_basket", "Add something to the sale first.", "أضف أصنافًا إلى الفاتورة أولًا."));
        }

        // A cashier must not post a sale to a branch they do not work at.
        if (!current.CanSeeBranch(request.BranchId))
        {
            return Results.Json(ApiError.Create(
                "branch_forbidden",
                "You cannot record a sale for that branch.",
                "لا يمكنك تسجيل فاتورة لهذا الفرع."), statusCode: 403);
        }

        /* The approver is someone this request can vouch for: the signed-in
           user, or another user whose password was just given. Whether they
           may approve — and whether approval is needed at all — is decided
           in the procedure, against their permissions as they stand. */
        var approverId = ProcErrors.Blank(request.ApprovedByUserId);

        if (approverId is not null && !string.Equals(approverId, current.UserId, StringComparison.Ordinal))
        {
            await using var check = db.Create();

            var approver = await check.QuerySingleOrDefaultAsync<(string? Hash, string? Salt)>(new CommandDefinition(
                "SELECT PasswordHash, PasswordSalt FROM core.AppUser WHERE UserId = @UserId AND Status = N'active';",
                new { UserId = approverId }, cancellationToken: ct));

            if (string.IsNullOrEmpty(request.ApproverPassword) ||
                approver.Hash is null || approver.Salt is null ||
                !hasher.Verify(request.ApproverPassword, approver.Hash, approver.Salt))
            {
                return Results.UnprocessableEntity(ApiError.Create(
                    "approval_invalid",
                    "The approver's password is not correct.",
                    "كلمة مرور المعتمِد غير صحيحة.",
                    new Dictionary<string, string[]> { ["approverPassword"] = ["The approver's password is not correct."] }));
            }
        }

        var lines = new DataTable();
        lines.Columns.Add("ItemId", typeof(string));
        lines.Columns.Add("Quantity", typeof(decimal));
        lines.Columns.Add("UnitPriceH", typeof(long));
        lines.Columns.Add("LineDiscountH", typeof(long));
        lines.Columns.Add("Note", typeof(string));

        foreach (var line in request.Lines)
        {
            lines.Rows.Add(line.ItemId, line.Quantity, line.UnitPriceH,
                           line.LineDiscountH, (object?)line.Note ?? DBNull.Value);
        }

        var payments = new DataTable();
        payments.Columns.Add("Method", typeof(string));
        payments.Columns.Add("AmountH", typeof(long));
        payments.Columns.Add("Reference", typeof(string));

        foreach (var payment in request.Payments)
        {
            payments.Rows.Add(payment.Method, payment.AmountH,
                              (object?)payment.Reference ?? DBNull.Value);
        }

        var parameters = new DynamicParameters();
        parameters.Add("@BranchId", request.BranchId);
        parameters.Add("@CustomerId", request.CustomerId);
        parameters.Add("@ServedByUserId", request.ServedByUserId);
        parameters.Add("@CashierName", current.Username);
        parameters.Add("@DiscountId", request.DiscountId);
        parameters.Add("@DiscountH", request.DiscountH);
        parameters.Add("@TenderedH", request.TenderedH);
        parameters.Add("@IdempotencyKey", request.IdempotencyKey);
        parameters.Add("@ApprovedByUserId", approverId);
        parameters.Add("@OrderType", ProcErrors.Blank(request.OrderType)?.ToLowerInvariant());
        parameters.Add("@Lines", lines.AsTableValuedParameter("sales.SaleLineTable"));
        parameters.Add("@Payments", payments.AsTableValuedParameter("sales.SalePaymentTable"));
        parameters.Add("@SaleId", dbType: DbType.String, direction: ParameterDirection.Output, size: 40);
        parameters.Add("@InvoiceNumber", dbType: DbType.String, direction: ParameterDirection.Output, size: 40);

        await using var connection = db.Create();

        try
        {
            await connection.ExecuteAsync(new CommandDefinition(
                "sales.usp_CommitSale",
                parameters,
                commandType: CommandType.StoredProcedure,
                cancellationToken: ct));
        }
        catch (SqlException ex) when (ex.Number is (>= 52000 and < 53000) or 63050 or 63051)
        {
            // The procedure's own rules. These are business outcomes, not
            // faults, so they come back as 422 with the reason intact.
            return Results.Json(
                Translate(ex.Number, ex.Message),
                statusCode: StatusCodes.Status422UnprocessableEntity);
        }

        var saleId = parameters.Get<string>("@SaleId");
        var invoiceNumber = parameters.Get<string>("@InvoiceNumber");

        logger.LogInformation("Sale {Invoice} committed at {Branch}.", invoiceNumber, request.BranchId);

        return Results.Created($"/api/sales/{saleId}", new { saleId, invoiceNumber });
    }

    /// <summary>
    /// The dashboard figures, aggregated in SQL.
    ///
    /// Fetching the period's sales and summing them in the browser would work
    /// at seed scale and fall over at a year of trading — and it would pull
    /// every line across the wire to produce eight numbers. The database is
    /// where the rows already are.
    ///
    /// The previous period is returned alongside, because a total without a
    /// comparison says nothing about whether things are going well.
    /// </summary>
    private static async Task<IResult> AnalyticsAsync(
        ISqlConnectionFactory db, string? branchId, int days = 7,
        CancellationToken ct = default)
    {
        var window = days <= 0 ? 7 : Math.Min(days, 365);

        await using var connection = db.Create();

        await using var multi = await connection.QueryMultipleAsync(new CommandDefinition(
            """
            DECLARE @Start DATETIME2(0) = DATEADD(DAY, -@Days, SYSUTCDATETIME());
            DECLARE @PrevStart DATETIME2(0) = DATEADD(DAY, -(@Days * 2), SYSUTCDATETIME());

            /* Voided sales are excluded everywhere here: they are reversed in
               the ledger, and counting them would overstate every figure. */

            -- 1. This period
            SELECT
                ISNULL(SUM(s.TotalH), 0)                       AS SalesH,
                COUNT(*)                                       AS Transactions,
                ISNULL(AVG(CAST(s.TotalH AS BIGINT)), 0)       AS AverageH,
                ISNULL(SUM(s.TotalH - s.TaxH - ISNULL(c.CostH, 0)), 0) AS GrossProfitH
            FROM sales.Sale AS s
            OUTER APPLY (
                SELECT SUM(l.UnitCostH * l.Quantity) AS CostH
                FROM sales.SaleLine AS l WHERE l.SaleId = s.SaleId
            ) AS c
            WHERE s.Status <> N'voided'
              AND s.SoldAtUtc >= @Start
              AND (@BranchId IS NULL OR s.BranchId = @BranchId);

            -- 2. The period before it, for comparison
            SELECT
                ISNULL(SUM(s.TotalH), 0)                       AS SalesH,
                COUNT(*)                                       AS Transactions,
                ISNULL(AVG(CAST(s.TotalH AS BIGINT)), 0)       AS AverageH,
                ISNULL(SUM(s.TotalH - s.TaxH - ISNULL(c.CostH, 0)), 0) AS GrossProfitH
            FROM sales.Sale AS s
            OUTER APPLY (
                SELECT SUM(l.UnitCostH * l.Quantity) AS CostH
                FROM sales.SaleLine AS l WHERE l.SaleId = s.SaleId
            ) AS c
            WHERE s.Status <> N'voided'
              AND s.SoldAtUtc >= @PrevStart AND s.SoldAtUtc < @Start
              AND (@BranchId IS NULL OR s.BranchId = @BranchId);

            -- 3. Daily totals
            SELECT
                CAST(s.SoldAtUtc AS DATE) AS [Date],
                SUM(s.TotalH)             AS SalesH
            FROM sales.Sale AS s
            WHERE s.Status <> N'voided'
              AND s.SoldAtUtc >= @Start
              AND (@BranchId IS NULL OR s.BranchId = @BranchId)
            GROUP BY CAST(s.SoldAtUtc AS DATE)
            ORDER BY [Date];

            -- 4. By payment method. Cash is stored as handed over (one row per
            --    sale), so the change given back is taken off to show takings.
            SELECT p.Method,
                   SUM(p.AmountH - CASE WHEN p.Method = N'cash' THEN s.ChangeH ELSE 0 END) AS AmountH
            FROM sales.SalePayment AS p
            JOIN sales.Sale AS s ON s.SaleId = p.SaleId
            WHERE s.Status <> N'voided'
              AND s.SoldAtUtc >= @Start
              AND (@BranchId IS NULL OR s.BranchId = @BranchId)
            GROUP BY p.Method;

            -- 5. Best sellers
            SELECT TOP (5)
                l.ItemId, l.NameAr, l.NameEn,
                SUM(l.Quantity)                          AS Quantity,
                SUM(l.UnitPriceH * l.Quantity - l.LineDiscountH) AS RevenueH
            FROM sales.SaleLine AS l
            JOIN sales.Sale AS s ON s.SaleId = l.SaleId
            WHERE s.Status <> N'voided'
              AND s.SoldAtUtc >= @Start
              AND (@BranchId IS NULL OR s.BranchId = @BranchId)
            GROUP BY l.ItemId, l.NameAr, l.NameEn
            ORDER BY RevenueH DESC;
            """,
            new { Days = window, BranchId = branchId },
            cancellationToken: ct));

        var current = await multi.ReadSingleAsync();
        var previous = await multi.ReadSingleAsync();
        var daily = (await multi.ReadAsync()).ToList();
        var byMethod = (await multi.ReadAsync()).ToList();
        var topItems = (await multi.ReadAsync()).ToList();

        return Results.Ok(new { current, previous, daily, byMethod, topItems });
    }

    private static async Task<IResult> ListAsync(
        ISqlConnectionFactory db,
        ICurrentUser current,
        string? branchId,
        string? search,
        DateOnly? from,
        DateOnly? to,
        int page = 1,
        int pageSize = 25,
        CancellationToken ct = default)
    {
        var paging = new PageQuery { Page = page <= 0 ? 1 : page, PageSize = pageSize };

        await using var connection = db.Create();

        const string sql = """
            SELECT COUNT(*)
            FROM sales.vw_SaleSummary AS s
            WHERE (@BranchId IS NULL OR s.BranchId = @BranchId OR s.BranchId IS NULL)
              AND (@Search IS NULL OR s.InvoiceNumber LIKE N'%' + @Search + N'%')
              AND (@From IS NULL OR CAST(s.SoldAtUtc AS DATE) >= @From)
              AND (@To   IS NULL OR CAST(s.SoldAtUtc AS DATE) <= @To);

            SELECT *
            FROM sales.vw_SaleSummary AS s
            WHERE (@BranchId IS NULL OR s.BranchId = @BranchId OR s.BranchId IS NULL)
              AND (@Search IS NULL OR s.InvoiceNumber LIKE N'%' + @Search + N'%')
              AND (@From IS NULL OR CAST(s.SoldAtUtc AS DATE) >= @From)
              AND (@To   IS NULL OR CAST(s.SoldAtUtc AS DATE) <= @To)
            ORDER BY s.SoldAtUtc DESC
            OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
            """;

        await using var multi = await connection.QueryMultipleAsync(new CommandDefinition(sql,
            new
            {
                BranchId = branchId,
                Search = string.IsNullOrWhiteSpace(search) ? null : search.Trim(),
                From = from,
                To = to,
                paging.Offset,
                paging.PageSize
            },
            cancellationToken: ct));

        var total = await multi.ReadSingleAsync<int>();
        var rows = (await multi.ReadAsync()).ToList();

        return Results.Ok(new PagedResult<object>
        {
            Items = rows.Cast<object>().ToList(),
            Page = paging.Page,
            PageSize = paging.PageSize,
            TotalCount = total
        });
    }

    private static async Task<IResult> GetAsync(
        string saleId,
        ISqlConnectionFactory db,
        CancellationToken ct)
    {
        await using var connection = db.Create();

        await using var multi = await connection.QueryMultipleAsync(new CommandDefinition(
            """
            SELECT * FROM sales.vw_SaleSummary WHERE SaleId = @SaleId;
            SELECT * FROM sales.SaleLine    WHERE SaleId = @SaleId ORDER BY SaleLineId;
            SELECT * FROM sales.SalePayment WHERE SaleId = @SaleId;
            """,
            new { SaleId = saleId },
            cancellationToken: ct));

        var sale = await multi.ReadSingleOrDefaultAsync();
        if (sale is null) return Results.NotFound();

        var lines = (await multi.ReadAsync()).ToList();
        var payments = (await multi.ReadAsync()).ToList();

        return Results.Ok(new { sale, lines, payments });
    }

    private static async Task<IResult> VoidAsync(
        string saleId,
        VoidSaleRequest request,
        ISqlConnectionFactory db,
        ICurrentUser current,
        CancellationToken ct)
    {
        await using var connection = db.Create();

        try
        {
            await connection.ExecuteAsync(new CommandDefinition(
                "sales.usp_VoidSale",
                new { SaleId = saleId, request.Reason, Actor = current.Username },
                commandType: CommandType.StoredProcedure,
                cancellationToken: ct));
        }
        catch (SqlException ex) when (ex.Number == 67012)
        {
            return ProcErrors.Conflict("sale_has_returns",
                "This sale has returns against it and cannot be voided. Return the remaining items instead.",
                "على هذه الفاتورة مرتجعات ولا يمكن إلغاؤها. أرجع الأصناف المتبقية بدلًا من ذلك.");
        }
        catch (SqlException ex) when (ex.Number >= 52000 && ex.Number < 53000)
        {
            return Results.Json(Translate(ex.Number, ex.Message),
                statusCode: StatusCodes.Status422UnprocessableEntity);
        }

        return Results.NoContent();
    }

    /// <summary>
    /// Turn a procedure's error number into a bilingual message.
    ///
    /// The database speaks English only, and an Arabic cashier should not meet
    /// an English error at the till.
    /// </summary>
    internal static ApiError Translate(int number, string fallback) => number switch
    {
        52000 => ApiError.Create("empty_basket",
            "A sale needs at least one line.", "الفاتورة تحتاج صنفًا واحدًا على الأقل."),
        52001 => ApiError.Create("bad_quantity",
            "Quantities must be above zero.", "يجب أن تكون الكميات أكبر من صفر."),
        52002 => ApiError.Create("unknown_item",
            "One of the items is no longer available.", "أحد الأصناف لم يعد متاحًا."),
        52003 => ApiError.Create("insufficient_stock",
            "There is not enough stock for one or more items.", "الكمية غير كافية لصنف أو أكثر."),
        52004 => ApiError.Create("discount_too_large",
            "The discount is more than the basket total.", "الخصم أكبر من إجمالي الفاتورة."),
        52005 => ApiError.Create("underpaid",
            "The payments do not cover the total.", "المدفوعات لا تغطي الإجمالي."),
        52006 => ApiError.Create("credit_needs_customer",
            "A credit sale needs a customer.", "البيع الآجل يحتاج إلى عميل."),
        52007 => ApiError.Create("over_credit_limit",
            "This would take the customer over their credit limit.",
            "هذا سيتجاوز حدّ الائتمان للعميل."),
        52010 => ApiError.Create("sale_not_found", "Sale not found.", "الفاتورة غير موجودة."),
        52011 => ApiError.Create("already_voided",
            "This sale is already voided.", "هذه الفاتورة ملغاة مسبقًا."),
        52012 => ApiError.Create("reason_required",
            "A void needs a reason.", "الإلغاء يحتاج إلى سبب."),
        52020 => ApiError.Create("bad_amount",
            "The amount must be above zero.", "يجب أن يكون المبلغ أكبر من صفر."),
        52021 => ApiError.Create("customer_not_found",
            "Customer not found.", "العميل غير موجود."),
        52022 => ApiError.Create("over_collection",
            "That is more than this customer owes.", "المبلغ أكبر مما على العميل."),
        52030 => ApiError.Create("bad_order_type",
            "Order type is dine_in, takeaway, delivery or other.",
            "نوع الطلب: محلي أو سفري أو توصيل أو أخرى."),
        52031 => ApiError.Create("non_cash_overpaid",
            "Card, bank and credit payments cannot exceed the total; only cash gives change.",
            "لا يمكن أن تتجاوز مدفوعات البطاقة أو التحويل أو الآجل الإجمالي؛ الباقي يُعاد نقدًا فقط."),
        63050 => ApiError.Create("discount_approval_required",
            "This discount is above its approval limit and needs approval from someone allowed to approve discounts.",
            "هذا الخصم يتجاوز حد الموافقة ويحتاج موافقة من شخص مخوّل باعتماد الخصومات."),
        63051 => ApiError.Create("approver_not_allowed",
            "The approver is not allowed to approve discounts.",
            "المعتمِد غير مخوّل باعتماد الخصومات."),
        _ => ApiError.Create("sale_failed", fallback, "تعذّر إتمام العملية.")
    };
}
